<?php require 'config.php';if($_SERVER['REQUEST_METHOD']!=='POST')exit('Invalid');check_csrf();$id=(int)($_POST['feature_id']??0);$email=trim($_POST['email']??'');if(!$id||!filter_var($email,FILTER_VALIDATE_EMAIL)){flash('Enter a valid email.','bad');header('Location:index.php');exit;}try{$s=db()->prepare('INSERT INTO votes(feature_id,voter_email) VALUES(?,?)');$s->execute([$id,strtolower($email)]);db()->prepare('UPDATE features SET votes=votes+1 WHERE id=?')->execute([$id]);flash('Thanks — your vote was counted.');}catch(PDOException $e){flash('You already voted for this feature.');}$q=db()->prepare('SELECT slug FROM features WHERE id=?');$q->execute([$id]);$slug=$q->fetchColumn();header('Location:feature.php?slug='.urlencode($slug));
